import{_ as a,o as t,c as o,ae as d}from"./chunks/framework.BX6FPmO9.js";const h=JSON.parse('{"title":"ADR：Metadata Catalog POC — GenUI、MCP、Policy-as-Code","description":"","frontmatter":{},"headers":[],"relativePath":"adr/stateless-mcp-genui-metadata.md","filePath":"adr/stateless-mcp-genui-metadata.md"}'),c={name:"adr/stateless-mcp-genui-metadata.md"};function r(s,e,n,l,i,p){return t(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="adr-metadata-catalog-poc-—-genui、mcp、policy-as-code" tabindex="-1">ADR：Metadata Catalog POC — GenUI、MCP、Policy-as-Code <a class="header-anchor" href="#adr-metadata-catalog-poc-—-genui、mcp、policy-as-code" aria-label="Permalink to &quot;ADR：Metadata Catalog POC — GenUI、MCP、Policy-as-Code&quot;">​</a></h1><p><strong>狀態</strong>：Accepted（POC）<br><strong>日期</strong>：2026-06-22</p><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>需要可演示的 OpenMetadata 風格 catalog，並對齊 2026 Stateless MCP 與 Generative UI 趨勢，同時避免權限規則散落於前後端 <code>if/else</code>。</p><h2 id="決策" tabindex="-1">決策 <a class="header-anchor" href="#決策" aria-label="Permalink to &quot;決策&quot;">​</a></h2><ol><li><strong>獨立 <code>/metadata</code> 模組</strong>（不修改 <code>/catalog-search</code> T-2026-004）。</li><li><strong>Declarative GenUI</strong>：<code>app/components/shared/genui</code> + Zod registry；未知 component 拒絕渲染。</li><li><strong>Static GenUI</strong>：<code>metadata.lookup</code> agent tool → 結構化 catalog 結果。</li><li><strong>Stateless MCP spike</strong>：<code>POST /api/mcp/gateway</code>、<code>.well-known/mcp.json</code>；每次請求帶 <code>_meta</code>。</li><li><strong>Policy-as-Code</strong>：<code>specs/policies/access-request.rego</code> + <code>opa test</code>；runtime 預設 in-process fallback，<code>OPA_URL</code> 可切換 live OPA。</li><li><strong>Data Contract</strong>：<code>specs/datacontracts/customer-profile.yaml</code> 對齊 <code>tbl-customers</code> fixture。</li><li><strong>Context packs</strong>：可插拔領域 fixture 見 <a href="./context-pack-domain-binding.html">context-pack-domain-binding.md</a>；預設 <code>enterprise-mau</code>。</li></ol><h2 id="分層" tabindex="-1">分層 <a class="header-anchor" href="#分層" aria-label="Permalink to &quot;分層&quot;">​</a></h2><table tabindex="0"><thead><tr><th>層</th><th>位置</th></tr></thead><tbody><tr><td>OpenAPI + Zod</td><td><code>specs/openapi</code>、<code>packages/shared-contracts</code></td></tr><tr><td>Data Contract</td><td><code>specs/datacontracts/</code></td></tr><tr><td>Policy</td><td><code>specs/policies/</code></td></tr><tr><td>Catalog data</td><td><code>content/context-packs/</code>（預設 <code>enterprise-mau</code>）；過渡 <code>content/metadata-assets.json</code></td></tr><tr><td>Remix UI</td><td><code>app/features/metadata</code>、<code>app/routes/metadata.*</code></td></tr><tr><td>Backend API</td><td><code>backend/src/routes/metadata.ts</code></td></tr></tbody></table><h2 id="延後" tabindex="-1">延後 <a class="header-anchor" href="#延後" aria-label="Permalink to &quot;延後&quot;">​</a></h2><ul><li>MCP Apps sandbox iframe</li><li>Playwright E2E</li><li>AsyncAPI / Pact / Buf</li><li>完整多級審批工作流</li></ul><h2 id="相關" tabindex="-1">相關 <a class="header-anchor" href="#相關" aria-label="Permalink to &quot;相關&quot;">​</a></h2><ul><li><a href="./backend-spec-layer-opa.html">backend-spec-layer-opa.md</a></li><li><a href="./spec-driven-contracts-and-sot.html">spec-driven-contracts-and-sot.md</a></li></ul>',12)])])}const g=a(c,[["render",r]]);export{h as __pageData,g as default};
